 function navItem(item:Page){const count=item==='Activity'?noticeCount:item==='Messages'?conversations.reduce((n,c)=>n+c.unread,0):0;return <Pressable key={item} accessibilityRole="button" accessibilityState={{selected:page===item}} onPress={()=>navigate(item)} style={[s.navItem,page===item&&s.navActive]}><Text style={[s.navText,page===item&&{color:colors.accent}]}>{item}{count?` · ${count}`:''}</Text></Pressable>;}
 const navigation=<View style={{gap:4}}>{navItem('Home')}{navItem('Sparks')}{navItem('Activity')}{folders.map(folder=><View key={folder.label}><Pressable accessibilityRole="button" accessibilityState={{expanded:folderOpen===folder.label}} onPress={()=>setFolderOpen(folderOpen===folder.label?null:folder.label)} style={s.navItem}><Text style={[s.navText,folder.pages.includes(page)&&{color:colors.accent}]}>{folder.label} {folderOpen===folder.label?'▾':'▸'}</Text></Pressable>{folderOpen===folder.label&&<View style={{paddingLeft:14,borderLeftWidth:2,borderColor:colors.lime,marginLeft:12}}>{folder.pages.map(navItem)}</View>}</View>)}{user?.isAdmin&&navItem('Moderation')}<Button small secondary label={dark?'Dark mode · On':'Dark mode · Off'} onPress={()=>setChoice(dark?'light':'dark')}/><Button small secondary label={choice==='system'?'Following phone theme':'Use phone theme'} onPress={()=>setChoice('system')}/>{!wide&&<Button small secondary label="Sign out" onPress={signOut} disabled={disabled}/>}</View>;
 const [handoffComments,setHandoffComments]=useState<LiveComment[]>([]);
 useEffect(()=>{if(!liveConnection?.id)return;let active=true;const load=()=>request<LiveComment[]>(`/live/${liveConnection.id}/chat`,null).then(v=>{if(active)setHandoffComments(v);void request<{dominantId:string|null}>(`/live/${liveConnection.id}`,null).then(room=>{if(active)setHandoffFocus(room.dominantId);}).catch(()=>{});}).catch(()=>{});void load();const timer=setInterval(()=>void load(),3000);return()=>{active=false;clearInterval(timer);};},[liveConnection]);
 if(liveConnection)return <SafeAreaView style={s.screen}><ScrollView contentContainerStyle={s.content}><Brand/><LiveTransport connection={liveConnection} dominantId={handoffFocus} comments={handoffComments} onEnd={liveConnection.endToken&&liveConnection.id?async()=>{await request(`/live/${liveConnection.id}/end-browser`,null,'POST',{endToken:liveConnection.endToken});setLiveConnection(null);}:undefined}/><Button label="Leave broadcast" onPress={()=>setLiveConnection(null)}/></ScrollView></SafeAreaView>;
