   {forgot?<><Button disabled={disabled} label="Send reset link" onPress={()=>job('reset-request',async()=>{const r=await request<{message:string}>('/auth/forgot-password',null,'POST',{email});setMessage(r.message);})}/><Button secondary label="Back to sign in" onPress={()=>{setForgot(false);setRegister(false);}}/></>:<><Button disabled={disabled||(register&&!consent)} label={busy==='auth'?'Connecting…':register?'Create account →':'Sign in →'} onPress={authenticate}/><Button secondary label={register?'Already here? Sign in':'New here? Create an account'} onPress={()=>{setRegister(!register);setError('');}} disabled={disabled}/><Button secondary label="Forgot password?" onPress={()=>{setForgot(true);setError('');}}/></>}
   <Text style={[s.muted,{fontSize:12}]}>Use an email you can access and a unique password. You’ll receive a verification link. Read our privacy policy and community rules before joining.</Text>
