  <View style={[s.header,!wide&&{paddingHorizontal:12,paddingVertical:10}]}><Pressable accessibilityRole="button" onPress={()=>navigate('Home')}><Brand/></Pressable><View style={s.row}>{wide&&<Text numberOfLines={1} style={[s.muted,{maxWidth:120}]}>@{user.username}</Text>}<Pressable accessibilityRole="button" accessibilityLabel="Create a post" onPress={quickPost} style={{backgroundColor:colors.accent,borderRadius:10,width:44,height:44,alignItems:'center',justifyContent:'center'}}><Text style={{fontSize:28,fontWeight:'500',color:colors.dark}}>＋</Text></Pressable>{wide?<Button small secondary disabled={disabled} label="Sign out" onPress={signOut}/>:<Pressable accessibilityRole="button" accessibilityLabel="Main menu" accessibilityState={{expanded:menuOpen}} onPress={()=>setMenuOpen(!menuOpen)} style={[s.navItem,{backgroundColor:colors.tint,minHeight:44,justifyContent:'center'}]}><Text style={s.navText}>{menuOpen?'Close ▴':'Menu ▾'}</Text></Pressable>}</View></View>
