    {page==='Contact'&&<View style={[s.card,{gap:14}]}><Text style={s.body}>Send a question, privacy request, or request for review. Your request appears in the operator’s support queue.</Text>{!!supportEmail&&<Text selectable style={s.body}>Email: {supportEmail}</Text>}<Field value={support} onChange={setSupport} placeholder="How can we help?" maxLength={4000} multiline/><Button disabled={disabled||support.trim().length<5} label="Send request" onPress={()=>job('support',async()=>{await api('/support','POST',{body:support});setSupport('');await load();setMessage('Request received. The operator can review it in Gather.');})}/>{tickets.map(t=><View key={t.id} style={s.banner}><Text style={s.sectionTitle}>{t.kind} #{t.id} · {t.resolved?'Resolved':'In review'}</Text><Text style={s.body}>{t.reason}</Text>{!!t.reply&&<Text style={s.body}>Gather response: {t.reply}</Text>}</View>)}</View>}
